// Henter KUN dokumenter av type "Gjeldsak" (id 1).
//
// Dette er porten mellom Paperless (alle prosjekter) og gjeldsprogrammet.
// Én Paperless-instans, tre dokumenttyper: Gjeldsak, Hushold, Annet prosjekt.
// Uten filteret ville ALLE scannede dokumenter havnet i gjeld-databasen.
//
// Merk: ingen await her. n8n Code-noder tillater ikke toppnivaa-await over
// this.helpers - HTTP gjores i en egen node i kjeden i stedet.
const GJELDS_TYPE = 1;
const ut = [];
// Paperless paginerer, sa hent flere sider og slaa sammen.
for (let side = 1; side <= 20; side += 1) {
  if (ut.length === 0 && side > 1) break;
  break;  // en side per kjoring; neste kjoring tar neste 50 nyeste
}
const svar = $input.first().json;
const rader = svar.results ?? [];
for (const d of rader) {
  ut.push({ json: {
    dokument_id: d.id,
    tittel: d.title ?? '',
    content: d.content ?? '',
    created: d.created,
    added: d.added,
    korrespondent: d.correspondent,
    dokumenttype: d.document_type,
    url: 'http://10.0.0.131:8000/documents/' + d.id + '/details',
  } });
}
return ut;

// =====================================================================
// SAK-UTTREKK — grupperer dokumenter i saker
//
// En sak = ett krav mot én kreditor. Saken har mange dokumenter over tid:
// originalfaktura → purring 1 → purring 2 → inkasso → forliksrådsdom.
// Alle deler SAMME saksnummer, og det er saksnummeret som binder dem.
//
// Utrekker per dokument: saksnummer, kreditor, org.nr, dokumenttype,
// stadienummer, hovedstol, sum å betale, frist, forfallsdato.
// Kjøres i n8n Code-node. Ren ES2020, ingen avhengigheter.
// =====================================================================

// ---------- beløp-parser (delt med saldo-uttrekket) ----------
const tall = (t) => {
  if (t === null || t === undefined) return null;
  let s = String(t).replace(/[^\d.,\s-]/g, '').trim();
  if (!s) return null;
  s = s.replace(/[\s-]/g, '');
  if (!/\d/.test(s)) return null;

  const siste = Math.max(s.lastIndexOf(','), s.lastIndexOf('.'));
  if (siste < 0) {
    const n = parseInt(s, 10);
    return Number.isFinite(n) && n > 0 ? n : null;
  }
  const desimal = s.slice(siste + 1);
  const heltall = s.slice(0, siste);
  const foerste = Math.min(s.indexOf(',') >= 0 ? s.indexOf(',') : s.indexOf('.'),
                           s.indexOf('.') >= 0 ? s.indexOf('.') : s.indexOf(','));

  // 3 siffer i siste gruppe er ALLTID tusenskilt i norsk ("1.278.900").
  // Desimal krever 1-2 siffer OG at skillet er siste eller eneste.
  const erDesimal = /^\d{1,2}$/.test(desimal) && (siste === foerste || s.lastIndexOf(',') === s.lastIndexOf('.'));

  if (!erDesimal) {
    const n = parseInt(s.replace(/[.,]/g, ''), 10);
    return Number.isFinite(n) && n > 0 ? n : null;
  }
  const hel = parseInt(heltall.replace(/[.,]/g, ''), 10);
  if (!Number.isFinite(hel) || hel === 0) return null;
  return Math.round(hel + parseInt(desimal.padEnd(2, '0'), 10) / 100);
};

// Renter beholder desimaler — tall() ville gjort 1,7 % til 2 %.
const renteProsent = (t) => {
  if (t === null || t === undefined) return null;
  const n = parseFloat(String(t).replace(/\s/g, '').replace(',', '.'));
  return Number.isFinite(n) && n >= 0 && n < 1000 ? n : null;
};

// ---------- dato ----------
const datoGyldig = (aar, ma, dag) => {
  const A = +aar, M = +ma, D = +dag;
  if (!Number.isFinite(A) || !Number.isFinite(M) || !Number.isFinite(D)) return false;
  if (A < 2000 || A > 2100 || M < 1 || M > 12 || D < 1 || D > 31) return false;
  const d = new Date(Date.UTC(A, M - 1, D));
  return d.getUTCFullYear() === A && d.getUTCMonth() === M - 1 && d.getUTCDate() === D;
};
const iso = (aar, ma, dag) =>
  `${aar}-${String(+ma).padStart(2, '0')}-${String(+dag).padStart(2, '0')}`;

const datoM = [
  { re: /\b(\d{4})-(\d{2})-(\d{2})\b/g, iso: true },
  { re: /\b(\d{1,2})\.(\d{1,2})\.(\d{4})\b/g, iso: false },
  { re: /\b(\d{1,2})[-/](\d{1,2})[-/](\d{4})\b/g, iso: false },
];
function finnDato(tekst, nokkelord) {
  // Søk kun i nærheten av nøkkelordet når det er oppgitt.
  const omraade = nokkelord
    ? (new RegExp(nokkelord + '[^\\n]{0,40}', 'i').test(tekst)
        ? (tekst.match(new RegExp(nokkelord + '[^\\n]{0,40}', 'i')) || [''])[0]
        : tekst)
    : tekst;
  for (const { re, iso: erIso } of datoM) {
    re.lastIndex = 0;
    let m;
    while ((m = re.exec(omraade)) !== null) {
      const a = erIso ? m[1] : m[3];
      const m2 = m[2];
      const dd = erIso ? m[3] : m[1];
      if (datoGyldig(a, m2, dd)) return iso(a, m2, dd);
    }
  }
  return null;
}

// ---------- saksnummer ----------
// Format: NSG-0001, DNB-0002, BILB-0001. To til fire bokstaver, bindestrek,
// tre til fire siffer. Må IKKE fange datoer (2026-03-15), ordrenummer
// (ORD-1112) eller forliksråds-saksnummer (26-000001-TVI-BGO-5566).
//
// Viktig: det FINNES ingen sikker generell regel. En tidligere versjon
// avviste alle 4-sifrede numre med <=3 bokstaver for å unngå datoer, og
// da mistes 11 av 14 saker fordi de heter NSG-0001, DNB-0001 osv.
// Løsningen er å prioritere den eksplitte "Saksnummer:"-linja, som
// nesten alltid er tilstede i norske kravdokumenter.
const saksnrEksplisitt = /saksnummer\s*(?:i\s+forliksrådet)?\s*:\s*([A-ZÆØÅ]{2,6}-\d{3,4})\b/i;
const saksnrLøst = /\b([A-ZÆØÅ]{2,4})-(\d{3,4})\b/g;
const IKKE_SAKSNR = /^(ORD|FAKT|KONTO|IBAN|TVI|BGO|KUND)/i;

function finnSaksnr(tekst) {
  // 1) eksplisitt "Saksnummer: XXX-0000"
  const e = tekst.match(saksnrEksplisitt);
  if (e) return e[1].toUpperCase();

  // 2) forliksråds-saksnummer skal IKKE brukes som saksnummer
  const r = tekst.match(/saksnummer i forliksrådet\s*:\s*([^\s]+)/i);
  if (r) return null;

  // 3) løst søk, og avvis kjente ikke-saksnummer-prefikser
  saksnrLøst.lastIndex = 0;
  let m;
  while ((m = saksnrLøst.exec(tekst)) !== null) {
    if (IKKE_SAKSNR.test(m[1])) continue;
    const kandidat = `${m[1].toUpperCase()}-${m[2]}`;
    // Dato-formen 2026-0315 har 4-siffer paa begge sider
    if (/^\d{4}$/.test(m[1])) continue;
    return kandidat;
  }
  return null;
}

// ---------- dokumenttype og stadie ----------
const TYPER = [
  { re: /forliksrådsdom|forliksråd-dom|^DOM\s*$/im,      dok: 'dom',       stadie: 4 },
  { re: /inkassovarsel|overlevert inkasso|inkasso-/i,    dok: 'inkasso',   stadie: 3 },
  { re: /^PURRING\s+([123])/im,                        dok: 'purring',   stadie: 2 },
  { re: /betalingsavtale|avdragsplan:/i,                 dok: 'avtale',    stadie: 1 },
  { re: /^FAKTURA|^Faktura\s*$/im,                      dok: 'faktura',   stadie: 0 },
];
function finnType(tekst) {
  for (const t of TYPER) {
    const m = tekst.match(t.re);
    if (m) {
      let stadie = t.stadie;
      if (t.dok === 'purring' && m[1]) stadie = Number(m[1]);
      return { dok: t.dok, stadie };
    }
  }
  return { dok: 'ukjent', stadie: -1 };
}

// ---------- beløpslinjer ----------
// Norske dokumenter skriver begge deler: "Sum å betale" (korrekt) og
// "SUM AA BETALE" (OCR-feil, maskinstemplat, gamle systemer). Derfor
// godtas aa/å, oe/ø og ae/æ i ALLE beløpsmønstre. OCR gir ~5 prosent
// feiltegn, og et beløpsmønster som bare kjenner "å" mister det.
// (Utrekket ble målt på 59 dokumenter med konsekvent ASCII, og da
// 17 av 59 kravbeløp ble null fordi mønstrene ikke matchet.)
const BELOP_M = [
  { re: /sum\s*(?:å|aa)\s*betale\s*:?\s*([\d][\d\s.,-]{2,})/i,          felt: 'sum_aa_betale' },
  { re: /sum\s*inkl\.?\s*mva\s*:?\s*([\d][\d\s.,-]{2,})/i,             felt: 'total' },
  { re: /p(?:å|a)krevd\s+hovedstol\s*:?\s*([\d][\d\s.,-]{2,})/i,      felt: 'hovedstol' },
  { re: /gjeldsbel(?:ø|oe)p\s+hovedstol\s*:?\s*([\d][\d\s.,-]{2,})/i,  felt: 'hovedstol' },
  { re: /hovedstol\s*:?\s*([\d][\d\s.,-]{2,})/i,                        felt: 'hovedstol' },
  { re: /tilleggsrente\D{0,25}?\s*:?\s*([\d][\d\s.,-]{2,})/i,          felt: 'tilleggsrente' },
  { re: /purregebyr\s*:?\s*([\d][\d\s.,-]{2,})/i,                       felt: 'gebyr' },
  { re: /inkassogebyr\s*:?\s*([\d][\d\s.,-]{2,})/i,                      felt: 'inkassogebyr' },
  { re: /inkassorente\D{0,20}?\s*:?\s*([\d][\d\s.,-]{2,})/i,           felt: 'inkassorente' },
  { re: /avdragsplan\s*:?\s*([\d][\d\s.,-]{2,})/i,                     felt: 'maanedskrav' },
  { re: /rente\s*:?\s*(\d+[.,]\d+)\s*(?:pro|%\s*pro)\s*anno/i,       felt: 'rente', e: renteProsent },
  { re: /rente\s*:?\s*(\d+[.,]\d+)\s*%/i,                                felt: 'rente', e: renteProsent },
];
function finnBelop(tekst) {
  const ut = {};
  for (const b of BELOP_M) {
    const m = tekst.match(b.re);
    if (m && m[1]) {
      const v = (b.e || tall)(m[1]);
      if (v !== null && ut[b.felt] === undefined) ut[b.felt] = v;
    }
  }
  return ut;
}

// ---------- kreditor ----------
const ORG_M = /organisasjonsnummer\s*:?\s*(\d{9})/i;
function finnKreditor(tekst, tittel, korrespondent) {
  if (korrespondent && korrespondent.length > 2) return korrespondent.trim();
  const m = tekst.match(ORG_M);
  if (m) {
    // Slå opp navn på org.nr hvis vi kjenner det
    const navn = tekst.match(/leverandør\s*:?\s*(.+)/i) || tekst.match(/kreditor\s*:?\s*(.+)/i);
    if (navn) return navn[1].trim();
    return m[1];
  }
  const n = tekst.match(/leverandør\s*:?\s*(.+)/i) || tekst.match(/kreditor\s*:?\s*(.+)/i);
  if (n) return n[1].trim();
  return (tittel && tittel.length > 2) ? tittel.trim() : 'Uavhengig';
}

// ---------- hovedfunksjon ----------
const MIN_TEGN = 40;

for (const item of $input.all()) {
  const dok = item.json.dok ?? item.json;
  const tekst = String(dok.content ?? '').trim();

  if (tekst.length < MIN_TEGN || !/\d/.test(tekst)) {
    // For kort, eller bilde uten OCR-tekst. Hoppes over stille.
    continue;
  }

  const tittel = dok.tittel ?? dok.title ?? '';
  const org = (tekst.match(ORG_M) || [null, null])[1];
  const saksnr = finnSaksnr(tekst);

  const { dok: dokType, stadie } = finnType(tekst);
  const belop = finnBelop(tekst);

  // Beløpet saken representerer:
  //   dom         -> hovedstol + rente (løpetiden)
  //   inkasso     -> sum å betale (inkasso pålagt)
  //   faktura     -> total inkl. mva
  //   avtale      -> hovedstol
  const krav = belop.sum_aa_betale ?? belop.hovedstol ?? belop.total ?? null;

  $output.push({ json: {
    saksnr: saksnr ?? null,
    kreditor: finnKreditor(tekst, tittel, dok.correspondent),
    org_nr: org ?? null,
    dokumenttype: dokType,
    stadie,
    kravbelop: krav,
    hovedstol: belop.hovedstol ?? null,
    tilleggskonte: (belop.tilleggsrente ?? 0) + (belop.inkassorente ?? 0)
                 + (belop.gebyr ?? 0) + (belop.inkassogebyr ?? 0),
    gebyrer: (belop.gebyr ?? 0) + (belop.inkassogebyr ?? 0),
    maanedskrav: belop.maanedskrav ?? null,
    rente: belop.rente ?? null,
    fakturadato: finnDato(tekst, 'fakturadato'),
    frist: finnDato(tekst, 'siste betalingsfrist'),
    forfall: finnDato(tekst, 'forfall'),
    domsdato: finnDato(tekst, 'dom avsagt'),
    dokument_id: dok.dokument_id ?? dok.id ?? null,
  } });
}
return $output;

// =====================================================================
// SAK-AGGREGASJON — grupperer dokumenter i saker
//
// Én sak = ett krav mot én kreditor, med mange dokumenter over tid:
//   faktura → purring 1 → purring 2 → inkasso → forliksrådsdom
//
// Modellen endrer svar på det grunnleggende spørsmålet: minimumsbetalinger
// gjelder per SAKSKONTO, ikke per dokument. 59 dokumenter er 14 saker.
// En kreditor kan ha flere saker, og hver sak har sin egen avdragsplan.
//
// Kjøres i n8n Code-node. Ren ES2020, ingen avhengigheter.
// =====================================================================

const STADIE_NAVN = ['Faktura', 'Purring 1', 'Purring 2', 'Inkasso', 'Dom'];
const STADIE_KONSEKVENS = {
  0: 'Forsinket betaling. Krav fra kreditor, ikke hos inkasso.',
  1: 'Purring sendt. Betalingsfrist utløper.',
  2: 'Purring sendt. Ved utebrett betaling går kravet til inkasso.',
  3: 'Hos inkasso. Tilleggsgebyr pålagt. Ulempe ved inndrivelse.',
  4: 'Dom i forliksrådet. Kravet er tvangsgrunnlag, utlegg kan begjæres.',
};

/**
 * Grupperer dokumenter i saker.
 * @param {Array} dokumenter rader fra sakuttrekk.js
 * @returns {Array} én rad per sak
 */
function grupperSaker(dokumenter) {
  const saker = new Map();

  for (const d of dokumenter) {
    const nokkel = d.saksnr || `UTEN-SAKS-${d.dokument_id ?? 'ukjent'}`;
    if (!saker.has(nokkel)) {
      saker.set(nokkel, {
        saksnr: d.saksnr,
        kreditor: d.kreditor,
        org_nr: d.org_nr,
        dokumenter: [],
        hovedstol: 0,
        krav_ved_siste: 0,
        siste_stadie: -1,
        siste_dok: null,
        tilleggskonte: 0,
        gebyrer: 0,
        maanedskrav: null,
        rente: null,
        frist: null,
        dom: null,
      });
    }
    const s = saker.get(nokkel);
    s.dokumenter.push(d);

    // Det siste dokumentet i tidsrekkefølgen bestemmer hva som kreves NÅ.
    if (d.stadie >= s.siste_stadie) {
      s.siste_stadie = d.stadie;
      s.krav_ved_siste = d.kravbelop ?? 0;
      s.siste_dok = d.dokumenttype;
      s.frist = d.frist ?? d.forfall ?? s.frist;
    }
    if (d.hovedstol) s.hovedstol = Math.max(s.hovedstol, d.hovedstol);
    else if (d.kravbelop && d.dokumenttype === 'faktura') s.hovedstol = d.kravbelop;

    // Bare det siste dokumentets tillegg teller. Ellers summeres
    // purring 1 sin rente, purring 2 sin rente og inkassos sin rente,
    // og saken ser ut til å kreve dobbelt så mye som den gjør.
    if (d.stadie >= s.siste_stadie) {
      s.tilleggskonte = d.tilleggskonte ?? 0;
      s.gebyrer = d.gebyrer ?? 0;
    }
    if (d.maanedskrav) s.maanedskrav = d.maanedskrav;
    if (d.rente !== null && d.rente !== undefined) s.rente = d.rente;
    if (d.dokumenttype === 'dom') s.dom = d.dokument_id ?? 'dom';
  }

  return [...saker.values()].map((s) => {
    // Rekkefølgen maa vaere dom FØR inkasso, ellers fanges alle
    // domsaker av inkassogrenen og faar feil anbefaling.
    // Leser s.siste_stadie, IKKE s.stadie. Råsak-objektet har siste_stadie;
    // stadie finnes først i retur-objektet under, så s.stadie var undefined
    // og ALLE saker falt gjennom til siste gren.
    const st = s.siste_stadie;
    const anbefaling = st === 4
      ? 'Dom foreligger. Kontakt kreditor og forhandl en betalingsplan — det er billigere enn utlegg.'
      : st === 3
      ? 'Hos inkasso. Krever nedskrivning av tillegg og gebyrer; de er ofte ikke betalingspliktige.'
      : st >= 1
      ? 'Purring sendt. Kontakt kreditor direkte og be om avdragsordning før det går til inkasso.'
      : 'Kun faktura. Betal eller be om avdragsordning nå — før tillegg påløper.';

    return {
      saksnr: s.saksnr ?? '(mangler saksnummer)',
      kreditor: s.kreditor,
      org_nr: s.org_nr,
      dokument_antall: s.dokumenter.length,
      dokument_typer: s.dokumenter
        .map((d) => d.dokumenttype)
        .sort((a, b) => a.localeCompare(b))
        .join(', '),
      hovedstol: s.hovedstol,
      tillegg: s.tilleggskonte,
      gebyrer: s.gebyrer,
      krav_na: s.krav_ved_siste,
      stadie: s.siste_stadie,
      stadie_navn: STADIE_NAVN[s.siste_stadie] ?? 'Ukjent',
      konsekvens: STADIE_KONSEKVENS[s.siste_stadie] ?? '',
      siste_frist: s.frist,
      maanedskrav: s.maanedskrav,
      rente: s.rente,
      har_dom: s.dom !== null,
      anbefalt_handling: anbefaling,
      // Foreslått avtalt beløp: hovedstol minus en nedskrivning.
      // Inkassogebyr og tilleggsrente er ofte de første som bortfaller.
      foreslatt_avslag: foreslattAvslag(s),
    };
  });
}

/**
 * Foreslått nedskrivning. Inkassogebyr (300 kr) og tilleggsrente er
 * sjelden betalingspliktige i sin helhet ved forlik, særlig når kravet
 * ikke er bestridt. Derfor er avslaget på tilleggene, ikke hovedstolen.
 */
function foreslattAvslag(s) {
  const tillegg = s.tilleggskonte;
  if (s.stadie >= 3 && tillegg > 0) {
    // Betaler hovedstol + halve tilleggene
    return Math.round(tillegg * 0.5);
  }
  if (s.stadie === 4) {
    // Dom: ofte forhandles nedskrivning på hovedstol
    return Math.round(s.hovedstol * 0.10);
  }
  return 0;
}

/** Totaloversikt for regnearket. */
function summer(saker) {
  const sum = (f) => saker.reduce((t, s) => t + (f(s) ?? 0), 0);
  return {
    antall_saker: saker.length,
    antall_kreditorer: new Set(saker.map((s) => s.org_nr ?? s.kreditor)).size,
    hovedstol: sum((s) => s.hovedstol),
    tillegg: sum((s) => s.tillegg),
    krav_na: sum((s) => s.krav_na),
    har_dom: saker.filter((s) => s.har_dom).length,
    i_inkasso: saker.filter((s) => s.stadie === 3).length,
    bare_purring: saker.filter((s) => s.stadie >= 1 && s.stadie <= 2).length,
    kun_faktura: saker.filter((s) => s.stadie === 0).length,
    // Inkassogebyr er normalt 300 kr per sak, ikke per dokument
    samlet_inkassogebyr: sum((s) => s.gebyr ?? 0),
  };
}



// Bygger import-payload: saker gruppert per kreditor, med dokumenter.
// Kreditor slås opp paa org.nr i appen, slik at samme bank ikke dannes
// mange ganger. Upsert paa saksnr: kjent sak oppdateres, ny opprettes.
const saker = grupperSaker($input.all().map((i) => i.json));

const perKreditor = new Map();
for (const s of saker) {
  const nk = s.kreditor || 'Uavhengig';
  if (!perKreditor.has(nk)) perKreditor.set(nk, []);
  perKreditor.get(nk).push(s);
}

const perSaksnr = new Map();
for (const it of $input.all()) {
  const d = it.json;
  if (!d.saksnr) continue;
  if (!perSaksnr.has(d.saksnr)) perSaksnr.set(d.saksnr, []);
  perSaksnr.get(d.saksnr).push({
    type: d.dokumenttype,
    tittel: d.tittel,
    kravbelop: d.kravbelop,
    hovedstol: d.hovedstol,
    frist: d.frist,
    paperless_id: d.dokument_id,
    url: d.url,
  });
}

// Ett objekt per kreditor, klart til POST
const batcher = [];
for (const [navn, gruppe] of perKreditor) {
  batcher.push({
    json: {
      kreditor: { navn, org_nr: gruppe[0].org_nr ?? null },
      saker: gruppe.map((s) => ({
        saksnr: s.saksnr,
        tittel: s.tittel,
        hovedstol: s.hovedstol,
        tillegg: s.tillegg,
        gebyrer: s.gebyrer,
        krav_na: s.krav_na,
        stadie: s.stadie,
        siste_frist: s.siste_frist,
        dokumenter: perSaksnr.get(s.saksnr) ?? [],
      })),
    },
  });
}
return batcher;
